function confirmChange(){if(!pending)return'Keine Änderung wartet auf Bestätigung.';if(locked)return'Speicher ist gesperrt. Keine Änderung ausgeführt.';const p=pending;pending=null;const b=backup('vorAenderung',JSON.stringify({...data,snapshots:[]}),3);if(!b)return'Abgebrochen: Sicherheitskopie konnte nicht erstellt werden.';if(p.type==='edit'){const f=data.facts.find(x=>x.id===p.id);if(!f)return'Fakt nicht mehr vorhanden.';const result=addFact(f.subject,f.property,p.value,'user',{replace:true});return result?'Fakt korrigiert: '+factInfo(result):'Speichern fehlgeschlagen.'}if(p.type==='deleteFact'){const f=data.facts.find(x=>x.id===p.id);if(!f)return'Fakt nicht mehr vorhanden.';return transaction(()=>{data.facts=data.facts.filter(x=>x.id!==p.id);audit('Wissensbank','Fakt gelöscht',f.id)})?'Fakt gelöscht: '+factInfo(f):'Speichern fehlgeschlagen.'}if(p.type==='forget'){const n=data.memory.length;const ok=transaction(()=>{data.memory=data.memory.filter(x=>!p.ids.includes(x.id));audit('Gedächtnis-KI','Erinnerungen gelöscht',String(n-data.memory.length))});return ok?`${n-data.memory.length} Erinnerung(en) gelöscht.`:'Speichern fehlgeschlagen.'}return'Unbekannte Änderung.'}
