// Nur ein zuvor ausdrücklich zugeordnetes Thema für eindeutige Pronomen-Folgefragen merken.
let neryxLastSubject=null;
async function routeAnswer(s,{allowTeaching=false}={}){
 const engine=window.NERYXOrchestrator;
 const follow=/^(?:und\s+)?(?:wo\s+(?:lebt|wohnt)|in\s+welchem\s+land\s+lebt)\s+(?:es|er|sie)\s*[?!.]?$/i.test(s.trim());
 if(follow){
  if(!neryxLastSubject)return 'NERYX · RÜCKFRAGE\nAuf welches Thema beziehst du dich? Bitte nenne den Namen.';
  s='Wo lebt das '+neryxLastSubject+'?';
 }
 const direct=window.NERYXCoordinator?.lookup?.(s);
 // Ein ausdrücklich neues, auch unbekanntes Thema beendet den alten Pronomenbezug.
 const explicit=window.NERYXTopicLearning?.parse?.(s);
 if(!follow&&explicit&&explicit.type!=='allgemein'&&explicit.subject&&
    explicit.subject!==neryxLastSubject)neryxLastSubject=null;
 if(direct?.subject&&direct.status!=='no_match'&&direct.status!=='entity_known_no_attribute')
  neryxLastSubject=direct.subject;
 if(!engine?.solve)return intelligentAnswer(s);
 const parsed=allowTeaching&&window.NERYXTopicLearning?.parse(s);
 if(!parsed)return engine.solve(s,{knowledge:intelligentAnswer});
 const checked=window.NERYXCoordinator?.lookup?.(s);
 if(checked&&checked.status!=='no_match')return engine.solve(s,{knowledge:intelligentAnswer});
 if(!checked){const coordinated=window.NERYXCoordinator?.decide(s);if(coordinated)return coordinated;}
 const original=await intelligentAnswer(s);
 const state=engine.classify?.(original);
 if(state==='no_match'){
  const known=window.NERYXTopicLearning?.match(s);
  return known||window.NERYXTopicLearning?.ask(s)||original;
 }
 return engine.solve(s,{knowledge:async()=>original});
}
