const UI={input:()=>$('input')||$('lb6-input')||$('chat-input')||$('user-input')||$('lb6-fallback-input'),chat:()=>$('log')||$('lb6-chat')||$('chat-messages')||$('messages')||$('lb6-fallback-chat'),send:()=>$('send')||$('lb6-send')||$('send-button')||$('send-btn')||$('lb6-fallback-send')};
/* =====================================================
   ANTWORT-KI 1.0 – SICHERE SCHNITTSTELLE
   ===================================================== */

async function intelligentAnswer(questionText) {
  const ai = window.LernBotAntwortKI;

  if (ai && typeof ai.answer === "function") {
    try {
      const result = await ai.answer(questionText, {
        facts: copy(data.facts),
        memories: copy(data.memory),
        documents: copy(data.documents),
        relationships: copy(data.relationships),
        context: copy(context)
      });

      if (
        result &&
        typeof result.text === "string" &&
        result.text.trim()
      ) {
        if (result.subject) {
          context.subject = result.subject;
        }

        if (result.property) {
          context.property = result.property;
        }

        return result.text;
      }
    } catch (error) {
      console.warn("Antwort-KI Fehler:", error);
    }
  }

  return knowledge(questionText);
}

function addMessage(role,content){const chat=UI.chat();if(!chat){console.log('LernBot',role,content);return}const e=document.createElement('div');e.className=role==='user'?'msg user':'msg bot'+(role==='system'?' system':'');const body=document.createElement('div');body.className='lb6-message-content';body.textContent=text(content);e.appendChild(body);chat.appendChild(e);chat.scrollTop=chat.scrollHeight}
function clearChat(){UI.chat()?.replaceChildren();addMessage('assistant','Neuer Chat. Dein gespeichertes Wissen bleibt erhalten.');context={subject:'',property:'',awaiting:null}}
async function send(){if(busy)return;const input=UI.input(),btn=UI.send();if(!input)return;const s=safe(input.value,100000);if(!s)return;busy=true;if(btn)btn.disabled=true;input.value='';addMessage('user',s);const typing=document.createElement('div');typing.className='msg bot lb6-typing';typing.textContent='NERYX denkt nach ...';UI.chat()?.appendChild(typing);try{const response=await handle(s);typing.remove();addMessage('assistant',response);const saved=transaction(()=>{data.log.push({id:uid(),time:now(),text:safe(s,4000),response:safe(response,1000)});if(data.log.length>150)data.log=data.log.slice(-150)});if(!saved)status('Antwort angezeigt – Protokoll nicht gespeichert')}catch(e){typing.remove();console.error(e);addMessage('assistant','Fehler: '+e.message)}finally{busy=false;if(btn)btn.disabled=false}}
