function sidebar(label,cmd){const c=norm(cmd),l=norm(label);if(c==='theme'||l.includes('theme')){const next=data.theme==='dark'?'light':'dark';if(transaction(()=>{data.theme=next})){document.documentElement.dataset.theme=next;document.body.dataset.theme=next;addMessage('system','Theme: '+next)}return}if(c==='import'||l.includes('import')){fileInput().click();return}if(c==='export'||l.includes('export')){addMessage('system',exportData());return}if(c==='refresh'||l.includes('aktualisieren')){location.reload();return}if(c==='verlauf loschen'){if(confirm('Chatverlauf wirklich löschen? Wissen bleibt erhalten.')){if(transaction(()=>{data.log=[]}))clearChat();else addMessage('system','Chatverlauf konnte nicht gespeichert werden.')}return}if(l.includes('neuer chat')){clearChat();return}if(l.includes('chatverlauf')){addMessage('assistant',data.log.length?data.log.map(x=>`${date(x.time)} – ${x.text||x.content||''}`).join('\n'):'Kein Chatverlauf.');return}if(l.includes('einstellungen')){addMessage('assistant',JSON.stringify(data.settings,null,2)+'\nTheme: '+data.theme);return}if(l.includes('code labor')){addMessage('assistant','Code prüfen: DEIN QUELLCODE');return}const target=c==='hilfe'||l==='hilfe'?'Hilfe':c==='was weisst du'||l.includes('wissensspeicher')?'Wissensübersicht':l.includes('agenten')?'Agenten':l.includes('projekte')?'Projekte':l.includes('dokumente')?'Dokumente':l.includes('speicher')?'Speicherdiagnose':null;if(target)handle(target).then(x=>addMessage('assistant',x))}
function start(){if(started||document.documentElement.dataset.lb6Started==='true')return;started=true;const style=document.createElement('style');style.id='lb6-paket40-style';style.textContent='.lb6-message-content{white-space:pre-wrap;overflow-wrap:anywhere}.lb6-typing{opacity:.7;font-style:italic}';document.head.appendChild(style);fallback();bind(UI.input(),'keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();send()}});bind(UI.send(),'click',e=>{e.preventDefault();send()});bind($('bar'),'submit',e=>{e.preventDefault();send()});bind(fileInput(),'change',fileChanged);document.querySelectorAll('#suggestions [data-msg]').forEach(el=>bind(el,'click',()=>{const input=UI.input();if(!input)return;input.value=el.dataset.msg;send()}));document.querySelectorAll('#drawer .side-button').forEach(el=>bind(el,'click',()=>sidebar(el.textContent,el.dataset.cmd||'')));document.querySelectorAll('[data-lb6-export], #lb6-export, #export-button, #export-btn').forEach(el=>bind(el,'click',()=>addMessage('system',exportData())));document.documentElement.dataset.lb6Started='true';document.documentElement.dataset.theme=data.theme;document.body.dataset.theme=data.theme;if(UI.chat()&&!UI.chat().children.length)addMessage('assistant','Hallo! Ich bin '+NAME+'.\nDein Wissen bleibt auf diesem Gerät.\nSchreibe „Hilfe“ für alle Befehle.');for(const n of notices)addMessage('system',n);status(locked?'Speicher gesperrt':'Bereit');console.log(NAME+' gestartet')}
